package br.com.playerprogramado;
import android.Manifest;import android.app.Activity;import android.content.pm.PackageManager;import android.graphics.Color;import android.os.*;import android.content.Context;import android.view.Gravity;import android.widget.*;import androidx.camera.core.*;import androidx.camera.lifecycle.ProcessCameraProvider;import androidx.camera.view.PreviewView;import androidx.core.app.ActivityCompat;import androidx.core.content.ContextCompat;import com.google.common.util.concurrent.ListenableFuture;import com.google.mlkit.vision.common.InputImage;import com.google.mlkit.vision.pose.*;import com.google.mlkit.vision.pose.defaults.PoseDetectorOptions;import java.util.concurrent.ExecutorService;import java.util.concurrent.Executors;import java.util.concurrent.atomic.AtomicBoolean;
public class PushupActivity extends androidx.activity.ComponentActivity {
 private PreviewView preview;private TextView countText,setText,statusText,timerText;private EditText targetInput,restInput;private Button startButton,stopButton;private final Handler handler=new Handler(Looper.getMainLooper());private ExecutorService cameraExecutor;private PoseDetector detector;private ProcessCameraProvider cameraProvider;private boolean workout=false,down=false,resting=false,cameraStarted=false;private int reps=0,sets=0,target=10,restSeconds=60,remaining=0;private long lastRepAt=0;private Runnable restTick;private final AtomicBoolean processing=new AtomicBoolean(false);
 public void onCreate(Bundle b){super.onCreate(b);cameraExecutor=Executors.newSingleThreadExecutor();detector=PoseDetection.getClient(new PoseDetectorOptions.Builder().setDetectorMode(PoseDetectorOptions.STREAM_MODE).build());buildUi();}
 private void buildUi(){LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(16,16,16,16);root.setBackgroundColor(0xFF080B0F);TextView title=new TextView(this);title.setText("CONTADOR DE FLEXÕES");title.setTextColor(-1);title.setTextSize(21);title.setTypeface(null,1);title.setGravity(17);root.addView(title);TextView hint=new TextView(this);hint.setText("Posicione o celular de lado, mostrando seu corpo inteiro. A câmera detecta a descida e a subida.");hint.setTextColor(0xFFB9C5D0);hint.setGravity(17);hint.setPadding(4,10,4,10);root.addView(hint);preview=new PreviewView(this);preview.setScaleType(PreviewView.ScaleType.FILL_CENTER);root.addView(preview,new LinearLayout.LayoutParams(-1,0,1));LinearLayout stats=new LinearLayout(this);stats.setGravity(17);countText=stat("0",stats,2);setText=stat("SÉRIE 0",stats,1);root.addView(stats);statusText=new TextView(this);statusText.setText("PRONTO PARA COMEÇAR");statusText.setTextColor(0xFF55C8F0);statusText.setTextSize(17);statusText.setTypeface(null,1);statusText.setGravity(17);statusText.setPadding(0,8,0,4);root.addView(statusText);timerText=new TextView(this);timerText.setText("DESCANSO  00:00");timerText.setTextColor(-1);timerText.setTextSize(20);timerText.setGravity(17);root.addView(timerText);
 LinearLayout settings=new LinearLayout(this);settings.setGravity(17);settings.setPadding(0,8,0,8);targetInput=field("10");restInput=field("60");LinearLayout c1=new LinearLayout(this);c1.setOrientation(1);label(c1,"META POR SÉRIE");c1.addView(targetInput,new LinearLayout.LayoutParams(-1,52));LinearLayout c2=new LinearLayout(this);c2.setOrientation(1);label(c2,"DESCANSO EM SEGUNDOS");c2.addView(restInput,new LinearLayout.LayoutParams(-1,52));settings.addView(c1,new LinearLayout.LayoutParams(0,-2,1));settings.addView(c2,new LinearLayout.LayoutParams(0,-2,1));root.addView(settings);
 startButton=new Button(this);startButton.setText("INICIAR TREINO AUTOMÁTICO");root.addView(startButton);stopButton=new Button(this);stopButton.setText("ENCERRAR TREINO");stopButton.setEnabled(false);root.addView(stopButton);startButton.setOnClickListener(v->startWorkout());stopButton.setOnClickListener(v->stopWorkout());setContentView(root);}
 private void label(LinearLayout l,String s){TextView t=new TextView(this);t.setText(s);t.setTextColor(-1);t.setTextSize(10);t.setGravity(17);l.addView(t);}
 private EditText field(String s){EditText e=new EditText(this);e.setSingleLine();e.setInputType(2);e.setText(s);e.setTextColor(-1);e.setGravity(17);e.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xFF55C8F0));return e;}
 private TextView stat(String s,LinearLayout p,float w){TextView t=new TextView(this);t.setText(s);t.setTextColor(-1);t.setTextSize(w>1?42:18);t.setTypeface(null,1);t.setGravity(17);p.addView(t,new LinearLayout.LayoutParams(0,-2,w));return t;}
 private void startWorkout(){try{target=Integer.parseInt(targetInput.getText().toString());restSeconds=Integer.parseInt(restInput.getText().toString());}catch(Exception e){target=10;restSeconds=60;}if(target<1||target>200||restSeconds<5||restSeconds>600){Toast.makeText(this,"Meta: 1 a 200. Descanso: 5 a 600 segundos.",1).show();return;}reps=0;sets=1;down=false;workout=true;resting=false;updateStats();targetInput.setEnabled(false);restInput.setEnabled(false);startButton.setEnabled(false);stopButton.setEnabled(true);statusText.setText("PREPARE-SE — POSICIONE-SE DE LADO");if(ContextCompat.checkSelfPermission(this,Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)ActivityCompat.requestPermissions(this,new String[]{Manifest.permission.CAMERA},77);else startCamera();}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==77&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)startCamera();else{Toast.makeText(this,"A câmera é necessária para contar as flexões.",1).show();stopWorkout();}}
 private void startCamera(){if(cameraStarted)return;ListenableFuture<ProcessCameraProvider> f=ProcessCameraProvider.getInstance(this);f.addListener(()->{try{cameraProvider=f.get();Preview p=new Preview.Builder().build();p.setSurfaceProvider(preview.getSurfaceProvider());ImageAnalysis a=new ImageAnalysis.Builder().setBackpressureStrategy(ImageAnalysis.STRATEGY_KEEP_ONLY_LATEST).build();a.setAnalyzer(cameraExecutor,this::analyze);cameraProvider.unbindAll();cameraProvider.bindToLifecycle(this,CameraSelector.DEFAULT_BACK_CAMERA,p,a);cameraStarted=true;statusText.setText("CÂMERA ATIVA — FAÇA UMA FLEXÃO");}catch(Exception e){statusText.setText("NÃO FOI POSSÍVEL ABRIR A CÂMERA");}},ContextCompat.getMainExecutor(this));}
 private void analyze(ImageProxy proxy){if(!processing.compareAndSet(false,true)){proxy.close();return;}android.media.Image media=proxy.getImage();if(media==null){processing.set(false);proxy.close();return;}detector.process(InputImage.fromMediaImage(media,proxy.getImageInfo().getRotationDegrees())).addOnSuccessListener(p->{if(!workout||resting)return;Float a=armAngle(p);if(a==null)return;long now=System.currentTimeMillis();if(a<95)down=true;else if(a>155&&down&&now-lastRepAt>500){down=false;lastRepAt=now;reps++;runOnUiThread(this::onRep);}}).addOnCompleteListener(t->{proxy.close();processing.set(false);});}
 private Float armAngle(Pose p){PoseLandmark s=best(p,11,12),e=best(p,13,14),w=best(p,15,16);if(s==null||e==null||w==null)return null;float ax=s.getPosition().x-e.getPosition().x,ay=s.getPosition().y-e.getPosition().y,bx=w.getPosition().x-e.getPosition().x,by=w.getPosition().y-e.getPosition().y;double dot=ax*bx+ay*by,mag=Math.sqrt((ax*ax+ay*ay)*(bx*bx+by*by));if(mag==0)return null;return(float)Math.toDegrees(Math.acos(Math.max(-1,Math.min(1,dot/mag))));}
 private PoseLandmark best(Pose p,int l,int r){PoseLandmark a=p.getPoseLandmark(l),b=p.getPoseLandmark(r);if(a==null)return b;if(b==null)return a;return a.getInFrameLikelihood()>=b.getInFrameLikelihood()?a:b;}
 private void onRep(){if(!workout)return;updateStats();statusText.setText("FLEXÃO "+reps+" DE "+target);if(reps>=target)beginRest();}
 private void beginRest(){resting=true;down=false;remaining=restSeconds;statusText.setText("SÉRIE CONCLUÍDA! DESCANSANDO");vibrate();tickRest();}
 private void tickRest(){timerText.setText(String.format(java.util.Locale.US,"DESCANSO  %02d:%02d",remaining/60,remaining%60));if(remaining<=0){resting=false;reps=0;sets++;updateStats();statusText.setText("VAMOS! PRÓXIMA SÉRIE");timerText.setText("DESCANSO  00:00");vibrate();return;}remaining--;restTick=this::tickRest;handler.postDelayed(restTick,1000);}
 private void updateStats(){countText.setText(String.valueOf(reps));setText.setText("SÉRIE "+sets);}
 private void vibrate(){try{Vibrator v=(Vibrator)getSystemService(Context.VIBRATOR_SERVICE);if(v!=null){if(Build.VERSION.SDK_INT>=26)v.vibrate(VibrationEffect.createOneShot(250,180));else v.vibrate(250);}}catch(Exception ignored){}}
 private void stopWorkout(){workout=false;resting=false;if(restTick!=null)handler.removeCallbacks(restTick);if(cameraProvider!=null)cameraProvider.unbindAll();cameraStarted=false;targetInput.setEnabled(true);restInput.setEnabled(true);startButton.setEnabled(true);stopButton.setEnabled(false);statusText.setText("TREINO ENCERRADO — "+sets+" SÉRIES");timerText.setText("DESCANSO  00:00");}
 protected void onDestroy(){super.onDestroy();if(cameraProvider!=null)cameraProvider.unbindAll();if(detector!=null)detector.close();if(cameraExecutor!=null)cameraExecutor.shutdown();handler.removeCallbacksAndMessages(null);}
}